logo h2 span{color:#d2ed9d}.welcome-sub{font:500 19px/1.48 'Space Grotesk';color:#f4f3e8;margin:14px 0 24px;letter-spacing:-.3px}.primary-btn{background:#d0ed9c;color:#22382d;padding:15px 19px;border-radius:7px;font:700 10px 'Space Grotesk';letter-spacing:1.4px;box-shadow:0 6px 20px #111f2344;transition:transform .2s,background .2s}.primary-btn:hover{transform:translateY(-2px);background:#def5b3}.primary-btn span{font-size:16px;margin-left:24px}.starter-note{margin-top:17px;color:#dfebd2b8;font-size:10px;display:flex;align-items:center;gap:9px}.starter-dots{display:flex;gap:3px}.starter-dots i{width:5px;height:5px;border-radius:50%;background:#d2ec9c}.starter-dots i:nth-child(2){opacity:.6}.starter-dots i:nth-child(3){opacity:.3}.welcome-foot{display:flex;gap:20px;margin-top:45px;color:#f1f3e3a8;font:700 8px 'Space Grotesk';letter-spacing:1.4px}.loading-screen{position:absolute;z-index:20;inset:0;background:#d7e3c9;display:flex;align-items:center;justify-content:center;gap:10px;color:#617c62;font:700 9px 'Space Grotesk';letter-spacing:2px;transition:opacity .4s}.loading-screen.done{opacity:0;pointer-events:none}.loading-mark{font-size:20px;color:#8aa96f;animation:pulse 1s infinite alternate}@keyframes pulse{to{transform:scale(1.3);opacity:.5}}.hidden{display:none!important}.toast{position:absolute;z-index:10;top:86px;left:50%;transform:translate(-50%,-10px);opacity:0;background:#20382f;color:white;padding:10px 16px;border-radius:7px;font-size:11px;box-shadow:0 8px 22px #12281c44;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.interact-prompt{position:absolute;z-index:4;bottom:130px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;border:1px solid #fff9;border-radius:8px;padding:8px 12px;background:#263f34d9;color:white;font-size:11px;box-shadow:0 5px 17px #19281d44}.interact-prompt span{padding:4px 6px;background:#d1ee9c;color:#26382d;border-radius:4px;font:700 9px 'Space Grotesk'}.dialogue{position:absolute;z-index:7;left:50%;bottom:32px;transform:translateX(-50%);width:min(650px,90vw);border:1px solid #f8f2d799;background:rgba(247,246,234,.97);box-shadow:0 14px 40px #17312766;border-radius:13px;padding:19px 23px}.speaker{font:700 9px 'Space Grotesk';letter-spacing:1.8px;color:#4b7552}.speaker small{color:#929b8c;font-size:8px;margin-left:7px}.dialogue p{font:500 15px/1.5 'Space Grotesk';margin:12px 0 16px}.dialogue button{float:right;background:#264638;color:#eef4df;padding:9px 12px;border-radius:6px;font:700 9px 'Space Grotesk';letter-spacing:1px}.dialogue button span{margin-left:14px;color:#d3ef9b}.battle-screen{position:absolute;z-index:6;inset:0;background:linear-gradient(180deg,#233a32dc 0%,transparent 24%,transparent 54%,#142c27bd 73%,#172c26ed 100%);color:#fff}.battle-top{position:absolute;left:50%;top:99px;transform:translateX(-50%);text-align:center}.battle-top small{font:700 8px 'Space Grotesk';letter-spacing:2px;color:#cfe69c}.battle-top h2{font:600 19px 'Space Grotesk';margin:7px 0;text-shadow:0 2px 12px #20352c}.battle-round{font:700 8px 'Space Grotesk';letter-spacing:1.5px;color:#ffffffa8}.battle-round span{color:#d2ed9d;margin:0 4px}.battle-creature-card{position:absolute;width:255px;padding:13px 15px;border-radius:11px;background:#faf9f0;color:#25382e;box-shadow:0 8px 28px #10241c55;display:flex;gap:12px;align-items:center}.enemy-card{right:12%;top:31%}.ally-card{left:11%;bottom:31%}.creature-avatar{width:59px;height:59px;border-radius:10px;background:#e6ecd9;position:relative;display:grid;place-items:center;overflow:hidden}.creature-avatar canvas{width:100%!important;height:100%!important}.creature-info{flex:1}.creature-name{display:flex;align-items:center;gap:7px}.creature-name b{font:600 14px 'Space Grotesk'}.creature-name span{background:#e5efdc;border-radius:4px;padding:3px 5px;color:#658164;font:700 7px 'Space Grotesk';letter-spacing:.6px}.level-label{font:600 9px 'Space Grotesk';color:#858e7f;margin:5px 0}.hp-track{height:5px;border-radius:4px;background:#e2e5d9;overflow:hidden}.hp-track i{height:100%;display:block;background:#76a870;transition:width .35s}.hp-track i.low{background:#e09b5f}.hp-label{font:600 8px 'Space Grotesk';color:#8e9788;display:block;margin-top:4px}.battle-log{position:absolute;left:50%;top:57%;transform:translate(-50%,-50%);padding:10px 16px;border-radius:7px;background:#203a32ba;text-align:center;font:500 12px 'Space Grotesk';min-width:280px;color:#eef1e1}.battle-actions{position:absolute;left:50%;bottom:20px;transform:translateX(-50%);width:min(560px,90vw)}.battle-tabs{display:flex;gap:6px;justify-content:center;margin-bottom:8px}.battle-tabs button{border:1px solid #e3edcc55;background:#1f382ec9;color:#cad5c5;border-radius:6px;padding:9px 13px;font:700 8px 'Space Grotesk';letter-spacing:1px}.battle-tabs button.active{background:#d2ed9f;color:#263a2d;border-color:#d2ed9f}.battle-options{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.move-btn,.option-btn{border:1px solid #eee9d099;background:#f7f5e9;color:#263a2d;border-radius:7px;padding:10px 12px;text-align:left;display:flex;justify-content:space-between;align-items:center;font:600 11px 'Space Grotesk';box-shadow:0 4px 15px #132b2244;transition:.15s}.move-btn:hover,.option-btn:hover{background:#e0f0bf;transform:translateY(-1px)}.move-btn small{font:700 7px 'Space Grotesk';letter-spacing:.8px;color:#779170}.move-btn em{font-style:normal;color:#758571;font:600 8px 'DM Sans'}.drawer{position:absolute;z-index:9;right:0;top:0;bottom:0;width:min(385px,100%);background:#f5f4e9;box-shadow:-15px 0 45px #1c332955;padding:29px 25px;animation:slidein .24s}.drawer-head{display:flex;justify-content:space-between;align-items:center}.drawer-head small{font:700 8px 'Space Grotesk';letter-spacing:1.8px;color:#8a9685}.drawer-head h2{margin:4px 0;font:600 27px 'Space Grotesk'}.close-btn{width:33px;height:33px;border-radius:50%;background:#e8ebde;color:#475c49;font-size:22px}.drawer-tabs{display:flex;gap:5px;margin:24px 0 18px;border-bottom:1px solid var(--line);padding-bottom:9px}.drawer-tabs button{background:transparent;padding:7px 10px;color:#7e887b;font:700 8px 'Space Grotesk';letter-spacing:1px}.drawer-tabs button.active{color:#416c4d;border-bottom:2px solid #6f9c64}.drawer-content{height:calc(100% - 130px);overflow-y:auto}.inventory-row,.team-row{display:flex;align-items:center;gap:12px;padding:13px 2px;border-bottom:1px solid var(--line)}.item-icon{width:40px;height:40px;border-radius:10px;background:#e4ecd8;display:grid;place-items:center;font-size:19px}.item-name{font:600 12px 'Space Grotesk'}.item-desc{font-size:10px;color:#839080;margin-top:3px}.item-count{margin-left:auto;font:700 12px 'Space Grotesk';color:#6b865e}.team-row{background:#fffdf5;padding:10px;border-radius:9px;margin:8px 0;border:1px solid #e5e8dc}.team-row .creature-avatar{width:44px;height:44px}.team-row .hp-track{margin-top:7px;width:155px}.menu-modal{position:absolute;z-index:11;inset:0;display:grid;place-items:center;background:#152a24a8;backdrop-filter:blur(5px)}.menu-card{position:relative;width:min(370px,90vw);background:#f7f6ec;border-radius:16px;padding:32px;text-align:center;box-shadow:0 15px 50px #12241d66}.menu-card .close-btn{position:absolute;right:16px;top:16px}.menu-emblem{margin:0 auto 15px;width:53px;height:53px;border-radius:16px;background:#e8efd9;color:#799c68;display:grid;place-items:center;font-size:24px}.menu-card>small{font:700 8px 'Space Grotesk';letter-spacing:1.8px;color:#83927d}.menu-card h2{font:600 23px 'Space Grotesk';margin:9px 0}.menu-card p{font-size:11px;color:#899185;margin:0 0 20px}.menu-option{width:100%;text-align:left;background:#e9eddf;margin:4px 0;border-radius:7px;padding:12px;font:600 11px 'Space Grotesk'}.menu-option span{float:right;color:#66845c}.menu-option.danger{color:#a05d4f;background:#f4e9e2}.touch-controls{display:none;position:absolute;z-index:4;left:14px;bottom:118px;width:122px;height:122px;grid-template:repeat(3,1fr)/repeat(3,1fr);gap:3px}.touch-controls button{border:1px solid #fff6;background:#263e34ad;color:white;border-radius:8px;font-size:14px;touch-action:none}.touch-controls button[data-dir=up]{grid-column:2;grid-row:1}.touch-controls button[data-dir=left]{grid-column:1;grid-row:2}.touch-controls button[data-dir=down]{grid-column:2;grid-row:2}.touch-controls button[data-dir=right]{grid-column:3;grid-row:2}@keyframes slidein{from{transform:translateX(20px);opacity:.7}to{transform:translateX(0);opacity:1}}
