import * as THREE from 'three';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=$('#world'), scene=new THREE.Scene(); scene.background=new THREE.Color(0x9dc9bc); scene.fog=new THREE.Fog(0x9dc9bc,27,73);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,120); camera.position.set(8,10,14);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.12;
scene.add(new THREE.HemisphereLight(0xe4f6e8,0x748557,2.1)); const sun=new THREE.DirectionalLight(0xffefcf,2.4); sun.position.set(-12,20,8); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-28;sun.shadow.camera.right=28;sun.shadow.camera.top=28;sun.shadow.camera.bottom=-28;scene.add(sun);
const mats={}; function mat(color,roughness=.92){const k=color+'-'+roughness;return mats[k]||(mats[k]=new THREE.MeshStandardMaterial({color,roughness}));}
const world=new THREE.Group(); scene.add(world); const nature=new THREE.Group();world.add(nature); const actors=new THREE.Group();world.add(actors); const battleStage=new THREE.Group();scene.add(battleStage);battleStage.visible=false;
const boxGeo=new THREE.BoxGeometry(1,1,1);
function cube(parent,x,y,z,sx,sy,sz,color,cast=true){const m=new THREE.Mesh(boxGeo,mat(color));m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m;}
// Block-built meadow, winding sandy path, creek and a distant ridge.
const ground=cube(nature,0,-.55,0,72,1,72,0x91b579,false); ground.receiveShadow=true;
for(let i=0;i<42;i++){let x=(Math.random()-.5)*62,z=(Math.random()-.5)*62;if(Math.abs(x)<4&&Math.abs(z)<5)continue;const color=[0x86aa70,0x94b77c,0x9abb7f,0x829f6c][Math.floor(Math.random()*4)];cube(nature,x,-.01,z,.85+Math.random()*1,.12,.8+Math.random()*.9,color,false)}
