const miniCamera=new THREE.OrthographicCamera(-32,32,32,-32,.1,100);miniCamera.position.set(0,40,0);miniCamera.lookAt(0,0,0);
const keys={};let mode='welcome',dialogueIndex=0,dialogueLines=[],nearNpc=false,activeBattle=null,battleBusy=false,encounterCooldown=0,walkTime=0,lastTime=0,bagTab='items',battleTab='moves',musicOn=true;
const save=()=>{try{localStorage.setItem('blockbound-save',JSON.stringify({v:1,...playerModel}))}catch{}};
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2300)}
function drawParty(){const list=$('#party-list');list.innerHTML='';for(const c of playerModel.party){const s=SPECIES[c.species];const row=document.createElement('div');row.className='party-pet';row.innerHTML=`<div class="pet-face" style="--pet-bg:#${s.color.toString(16)}">${s.icon}</div><div class="pet-label">${c.species}</div><div class="pet-hp"><i style="width:${Math.max(0,c.hp/c.maxHp*100)}%"></i></div>`;list.append(row)}for(let i=playerModel.party.length;i<3;i++){const e=document.createElement('div');e.className='party-empty';e.textContent='+';list.append(e)}$('#party-count').textContent=`${String(playerModel.party.length).padStart(2,'0')} / 06`;$('#quest-count').textContent=playerModel.questDone?'1/1':'0/1';$('#quest-progress').style.width=playerModel.questDone?'100%':'0%';}
drawParty();
function showPrompt(){const d=player.group.position.distanceTo(mira.group.position);nearNpc=d<4.2&&mode==='explore';$('#interact-prompt').classList.toggle('hidden',!nearNpc)}
function startDialogue(lines){dialogueLines=lines;dialogueIndex=0;mode='dialogue';$('#dialogue-text').textContent=lines[0];$('#dialogue').classList.remove('hidden');$('#interact-prompt').classList.add('hidden')}
function advanceDialogue(){dialogueIndex++;if(dialogueIndex>=dialogueLines.length){$('#dialogue').classList.add('hidden');mode='explore';if(!playerModel.metMira){playerModel.metMira=true;playerModel.questDone=true;save();drawParty();toast('Field note completed · First steps')}return}$('#dialogue-text').textContent=dialogueLines[dialogueIndex]}
function interact(){if(mode==='dialogue'){advanceDialogue();return}if(mode!=='explore')return;if(nearNpc){if(!playerModel.metMira)startDialogue(['Oh! A new face in Fernlight Meadow. I’m Mira, a field researcher.','The creatures here are called companions. They each have their own nature, moves, and little quirks.','There’s a Spriglet wandering near the flowers. Try a Glow Orb when it’s worn down—then it can join your crew!','A meadow’s a wonderful place to begin. Take your time out there, and come tell me what you find.']);else startDialogue(['Back among the wilds? The meadow is full of little surprises.','A Glow Orb works best when a wild companion is a bit tired. And keep Sunberries handy for your crew.']);return}const target=entityCreatures.find(m=>player.group.position.distanceTo(m.position)<2.7);if(target){beginBattle(target.userData.species||'Spriglet');return}if(Math.abs(player.group.position.x)<2.2&&Math.abs(player.group.position.z)<2.3){toast('Fernlight Meadow · A peaceful place to begin.');return}toast('There’s nothing close enough to interact with.')}
function battleOpen(species,wildData=null){const wild=wildData||makeCreature(species,2+Math.floor(Math.random()*4));activeBattle={wild,ally:playerModel.party.find(c=>c.hp>0)||playerModel.party[0],source:wildData?'world':'grass',enemyMesh:null};if(!activeBattle.ally.hp){activeBattle.ally.hp=Math.max(1,Math.floor(activeBattle.ally.maxHp*.45))}mode='battle';battleBusy=false;$('#battle-screen').classList.remove('hidden');$('#battle-title').textContent=`A wild ${wild.species} appeared!`;$('#enemy-name').textContent=wild.species;$('#enemy-type').textContent=wild.type;$('#enemy-level').textContent=wild.level;$('#ally-name').textContent=activeBattle.ally.species;$('#ally-type').textContent=activeBattle.ally.type;$('#ally-level').textContent=activeBattle.ally.level;$('#battle-log').textContent=`A wild ${wild.species} stepped out of the tall grass!`;const wildMesh=creatureMesh(wild);wildMesh.scale.setScalar(1.3);wildMesh.position.set(2.2,.65,-1.25);battleStage.add(wildMesh);activeBattle.enemyMesh=wildMesh;arenaPlayer.clear();const allyMesh=creatureMesh(activeBattle.ally);allyMesh.scale.setScalar(1.25);allyMesh.position.set(-2.2,.65,1.4);arenaPlayer.add(allyMesh);updateHp();setBattleTab('moves');save()}
function beginBattle(species){const target=entityCreatures.find(m=>player.group.position.distanceTo(m.position)<2.7);let data=null;if(target){const idx=entityCreatures.indexOf(target);actors.remove(target);entityCreatures.splice(idx,1);data=makeCreature(target.userData.species||species,3)}battleOpen(species,data)}
function updateHp(){if(!activeBattle)return;const w=activeBattle.wild,a=activeBattle.ally;$('#enemy-hp').style.width=`${Math.max(0,w.hp/w.maxHp*100)}%`;$('#ally-hp').style.width=`${Math.max(0,a.hp/a.maxHp*100)}%`;$('#enemy-hp').classList.toggle('low',w.hp/w.maxHp<.3);$('#ally-hp').classList.toggle('low',a.hp/a.maxHp<.3);$('#enemy-hp-label').textContent=`HP ${w.hp} / ${w.maxHp}`;$('#ally-hp-label').textContent=`HP ${a.hp} / ${a.maxHp}`}
function setBattleTab(tab){battleTab=tab;$$('.battle-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const box=$('#battle-options');box.innerHTML='';if(tab==='moves'){activeBattle.ally.moves.forEach((move,i)=>{const s=SPECIES[activeBattle.ally.species],el=document.createElement('button');el.className='move-btn';el.innerHTML=`<span>${move}<br><small>${i===0?s.type:'NORMAL'} · ${i===0?'POWER 14':'POWER 8'}</small></span><em>${i===0?'12':'∞'} PP</em>`;el.onclick=()=>attack(i);box.append(el)})}else if(tab==='team'){playerModel.party.forEach(c=>{const el=document.createElement('button');el.className='option-btn';el.innerHTML=`${c.species} · LV ${c.level} <small>${c.hp}/${c.maxHp} HP</small>`;el.disabled=c.hp<=0||c===activeBattle.ally;el.onclick=()=>switchAlly(c);box.append(el)})}else if(tab==='items'){for(const name of ['Glow Orb','Sunberry']){const el=document.createElement('button');el.className='option-btn';el.innerHTML=`${name} <small>× ${playerModel.items[name]||0}</small>`;el.disabled=!playerModel.items[name];el.onclick=()=>useBattleItem(name);box.append(el)}}else{const el=document.createElement('button');el.className='option-btn';el.textContent='Try to leave the meadow';el.onclick=()=>finishBattle('You stepped away from the encounter.');box.append(el)}}
$$('.battle-tabs button').forEach(b=>b.addEventListener('click',()=>setBattleTab(b.dataset.tab)));
